public class Solution{void F(char[][]b,int i,int j){if(i<0||j<0||i==b.Length||j==b[0].Length||b[i][j]!='O')return;b[i][j]='#';F(b,i+1,j);F(b,i-1,j);F(b,i,j+1);F(b,i,j-1);}public void Solve(char[][]b){if(b.Length==0)return;int m=b.Length,n=b[0].Length;for(int i=0;i<m;i++){F(b,i,0);F(b,i,n-1);}for(int j=0;j<n;j++){F(b,0,j);F(b,m-1,j);}for(int i=0;i<m;i++)for(int j=0;j<n;j++)b[i][j]=b[i][j]=='#'?'O':b[i][j]=='O'?'X':b[i][j];}}
